-- FUNC09 - Tributário e Receita Municipal. Migration aditiva, idempotente e sem dados operacionais fictícios.
create schema if not exists sigov;
create table if not exists sigov.tributario_contribuinte (id bigint generated by default as identity primary key, tipo_pessoa char(1) not null, documento varchar(14) not null, nome_razao_social varchar(250) not null, nome_fantasia varchar(180), inscricao_municipal varchar(40), email varchar(180), telefone varchar(30), endereco jsonb not null default '{}'::jsonb, responsavel_contabil jsonb, situacao varchar(20) not null default 'ATIVO', tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint ck_tc_tipo check(tipo_pessoa in('F','J')), constraint ck_tc_situacao check(situacao in('ATIVO','SUSPENSO','BAIXADO')), constraint ux_tc_doc unique(tenant_id,entidade_id,documento));
create table if not exists sigov.tributario_imovel (id bigint generated by default as identity primary key, inscricao_imobiliaria varchar(60) not null, proprietario_id bigint not null, responsavel_id bigint, logradouro varchar(250) not null, numero varchar(30), complemento varchar(120), bairro varchar(120) not null, setor varchar(40), quadra varchar(40), lote varchar(40), area_territorial numeric(18,4) not null default 0, area_construida numeric(18,4) not null default 0, testada numeric(18,4) not null default 0, uso varchar(80), padrao_construtivo varchar(80), situacao varchar(20) not null default 'ATIVO', valor_venal_territorial numeric(18,2) not null default 0, valor_venal_predial numeric(18,2) not null default 0, valor_venal_total numeric(18,2) generated always as (valor_venal_territorial+valor_venal_predial) stored, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_ti_prop foreign key(proprietario_id) references sigov.tributario_contribuinte(id), constraint fk_ti_resp foreign key(responsavel_id) references sigov.tributario_contribuinte(id), constraint ux_ti_insc unique(tenant_id,entidade_id,inscricao_imobiliaria), constraint ck_ti_val check(area_territorial>=0 and area_construida>=0 and testada>=0 and valor_venal_territorial>=0 and valor_venal_predial>=0));
create table if not exists sigov.tributario_imovel_historico (id bigint generated by default as identity primary key, imovel_id bigint not null, dados_anteriores jsonb not null, dados_novos jsonb not null, justificativa text not null, ocorrido_at timestamptz not null default now(), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tih_imovel foreign key(imovel_id) references sigov.tributario_imovel(id));
create table if not exists sigov.tributario_mobiliario (id bigint generated by default as identity primary key, contribuinte_id bigint not null, inscricao_municipal varchar(60) not null, documento varchar(14) not null, cnae_principal varchar(10) not null, regime_tributario varchar(60) not null, endereco_funcionamento jsonb not null, data_abertura date not null, data_baixa date, situacao varchar(20) not null default 'ATIVA', alvara_id bigint, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tm_contrib foreign key(contribuinte_id) references sigov.tributario_contribuinte(id), constraint ux_tm_insc unique(tenant_id,entidade_id,inscricao_municipal), constraint ck_tm_datas check(data_baixa is null or data_baixa>=data_abertura), constraint ck_tm_sit check(situacao in('ATIVA','SUSPENSA','BAIXADA')));
create table if not exists sigov.tributario_atividade (id bigint generated by default as identity primary key, codigo_cnae varchar(10) not null, descricao varchar(250) not null, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint ux_ta_cnae unique(tenant_id,entidade_id,codigo_cnae));
create table if not exists sigov.tributario_mobiliario_atividade (id bigint generated by default as identity primary key, mobiliario_id bigint not null, atividade_id bigint not null, principal boolean not null default false, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tma_m foreign key(mobiliario_id) references sigov.tributario_mobiliario(id), constraint fk_tma_a foreign key(atividade_id) references sigov.tributario_atividade(id), constraint ux_tma unique(tenant_id,entidade_id,mobiliario_id,atividade_id));
create table if not exists sigov.tributario_exercicio (id bigint generated by default as identity primary key, ano integer not null, inicio date not null, fim date not null, status varchar(20) not null default 'ABERTO', tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint ux_te_ano unique(tenant_id,entidade_id,ano), constraint ck_te_datas check(ano between 2000 and 2200 and fim>=inicio));
create table if not exists sigov.tributario_tributo (id bigint generated by default as identity primary key, codigo varchar(30) not null, nome varchar(120) not null, tipo varchar(30) not null, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint ux_tt_codigo unique(tenant_id,entidade_id,codigo), constraint ck_tt_tipo check(tipo in('IPTU','ISS','ITBI','TAXA','CONTRIBUICAO_MELHORIA','MULTA','JUROS')));
create table if not exists sigov.tributario_parametro_tributario (id bigint generated by default as identity primary key, exercicio_id bigint not null, tributo_id bigint not null, versao integer not null default 1, vigencia_inicio date not null, vigencia_fim date, aliquota numeric(12,6) not null default 0, faixa_inicial numeric(18,2), faixa_final numeric(18,2), desconto_percentual numeric(8,4) not null default 0, acrescimo_percentual numeric(8,4) not null default 0, multa_atraso_percentual numeric(8,4) not null default 0, juros_mes_percentual numeric(8,4) not null default 0, vencimento_regra jsonb not null default '{}'::jsonb, indexador varchar(40), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tpt_ex foreign key(exercicio_id) references sigov.tributario_exercicio(id), constraint fk_tpt_tr foreign key(tributo_id) references sigov.tributario_tributo(id), constraint ux_tpt_ver unique(tenant_id,entidade_id,exercicio_id,tributo_id,versao), constraint ck_tpt_val check(aliquota>=0 and desconto_percentual between 0 and 100 and acrescimo_percentual>=0 and multa_atraso_percentual>=0 and juros_mes_percentual>=0 and (faixa_final is null or faixa_inicial is null or faixa_final>=faixa_inicial)));
create table if not exists sigov.tributario_lancamento (id bigint generated by default as identity primary key, numero varchar(60) not null, contribuinte_id bigint not null, imovel_id bigint, mobiliario_id bigint, exercicio_id bigint not null, tributo_id bigint not null, competencia varchar(7), vencimento date not null, valor_principal numeric(18,2) not null, desconto numeric(18,2) not null default 0, acrescimos numeric(18,2) not null default 0, valor_total numeric(18,2) not null, status varchar(30) not null default 'ABERTO', revisao_justificativa text, cancelamento_justificativa text, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tl_c foreign key(contribuinte_id) references sigov.tributario_contribuinte(id), constraint fk_tl_i foreign key(imovel_id) references sigov.tributario_imovel(id), constraint fk_tl_m foreign key(mobiliario_id) references sigov.tributario_mobiliario(id), constraint fk_tl_e foreign key(exercicio_id) references sigov.tributario_exercicio(id), constraint fk_tl_t foreign key(tributo_id) references sigov.tributario_tributo(id), constraint ux_tl_num unique(tenant_id,entidade_id,numero), constraint ck_tl_val check(valor_principal>=0 and desconto>=0 and acrescimos>=0 and valor_total=valor_principal-desconto+acrescimos and valor_total>=0), constraint ck_tl_status check(status in('ABERTO','PAGO','VENCIDO','CANCELADO','DIVIDA_ATIVA','PARCELADO')), constraint ck_tl_cancel check(status<>'CANCELADO' or nullif(trim(cancelamento_justificativa),'') is not null));
create table if not exists sigov.tributario_lancamento_item (id bigint generated by default as identity primary key, lancamento_id bigint not null, descricao varchar(250) not null, valor numeric(18,2) not null, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tli_l foreign key(lancamento_id) references sigov.tributario_lancamento(id), constraint ck_tli_val check(valor>=0));
create table if not exists sigov.tributario_guia (id bigint generated by default as identity primary key, lancamento_id bigint not null, numero varchar(60) not null, emissao_at timestamptz not null default now(), vencimento date not null, valor numeric(18,2) not null, status varchar(20) not null default 'EMITIDA', via integer not null default 1, codigo_barras varchar(100), pix_payload text, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tg_l foreign key(lancamento_id) references sigov.tributario_lancamento(id), constraint ux_tg_num unique(tenant_id,entidade_id,numero), constraint ck_tg_val check(valor>=0 and via>0), constraint ck_tg_tecnico check(codigo_barras is null and pix_payload is null), constraint ck_tg_status check(status in('EMITIDA','PAGA','VENCIDA','CANCELADA')));
create table if not exists sigov.tributario_guia_parcela (id bigint generated by default as identity primary key, guia_id bigint not null, numero_parcela integer not null, vencimento date not null, valor numeric(18,2) not null, status varchar(20) not null default 'ABERTA', tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tgp_g foreign key(guia_id) references sigov.tributario_guia(id), constraint ux_tgp unique(tenant_id,entidade_id,guia_id,numero_parcela), constraint ck_tgp_val check(numero_parcela>0 and valor>=0));
create table if not exists sigov.tributario_lote_arrecadacao (id bigint generated by default as identity primary key, numero varchar(60) not null, origem varchar(80) not null, arquivo_hash varchar(128), recebido_at timestamptz not null default now(), quantidade integer not null default 0, valor_total numeric(18,2) not null default 0, status varchar(20) not null default 'RECEBIDO', tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint ux_tla_num unique(tenant_id,entidade_id,numero), constraint ck_tla_val check(quantidade>=0 and valor_total>=0));
create table if not exists sigov.tributario_pagamento (id bigint generated by default as identity primary key, guia_id bigint not null, lote_id bigint, pago_at timestamptz not null, valor_pago numeric(18,2) not null, desconto numeric(18,2) not null default 0, multa numeric(18,2) not null default 0, juros numeric(18,2) not null default 0, diferenca numeric(18,2) not null default 0, diferenca_justificativa text, status varchar(20) not null default 'CONFIRMADO', estorno_justificativa text, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tp_g foreign key(guia_id) references sigov.tributario_guia(id), constraint fk_tp_lote foreign key(lote_id) references sigov.tributario_lote_arrecadacao(id), constraint ck_tp_val check(valor_pago>=0 and desconto>=0 and multa>=0 and juros>=0), constraint ck_tp_dif check(diferenca=0 or nullif(trim(diferenca_justificativa),'') is not null), constraint ck_tp_est check(status<>'ESTORNADO' or nullif(trim(estorno_justificativa),'') is not null));
create table if not exists sigov.tributario_divida_ativa (id bigint generated by default as identity primary key, lancamento_id bigint not null, numero_inscricao varchar(60) not null, livro varchar(30), folha varchar(30), inscrita_at timestamptz not null default now(), valor_original numeric(18,2) not null, valor_atualizado numeric(18,2) not null, status varchar(20) not null default 'INSCRITA', cancelamento_justificativa text, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tda_l foreign key(lancamento_id) references sigov.tributario_lancamento(id), constraint ux_tda_num unique(tenant_id,entidade_id,numero_inscricao), constraint ck_tda_val check(valor_original>0 and valor_atualizado>=0), constraint ck_tda_cancel check(status<>'CANCELADA' or nullif(trim(cancelamento_justificativa),'') is not null));
create table if not exists sigov.tributario_parcelamento (id bigint generated by default as identity primary key, numero varchar(60) not null, contribuinte_id bigint not null, divida_ativa_id bigint, lancamento_id bigint, entrada numeric(18,2) not null default 0, quantidade_parcelas integer not null, valor_parcela numeric(18,2) not null, aprovado_at timestamptz, status varchar(20) not null default 'SIMULADO', rescisao_justificativa text, renegociacao_origem_id bigint, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tpar_c foreign key(contribuinte_id) references sigov.tributario_contribuinte(id), constraint fk_tpar_d foreign key(divida_ativa_id) references sigov.tributario_divida_ativa(id), constraint fk_tpar_l foreign key(lancamento_id) references sigov.tributario_lancamento(id), constraint fk_tpar_r foreign key(renegociacao_origem_id) references sigov.tributario_parcelamento(id), constraint ux_tpar_num unique(tenant_id,entidade_id,numero), constraint ck_tpar_vinc check(divida_ativa_id is not null or lancamento_id is not null), constraint ck_tpar_val check(entrada>=0 and quantidade_parcelas>0 and valor_parcela>0));
create table if not exists sigov.tributario_parcelamento_parcela (id bigint generated by default as identity primary key, parcelamento_id bigint not null, numero integer not null, vencimento date not null, valor numeric(18,2) not null, pago_at timestamptz, valor_pago numeric(18,2), status varchar(20) not null default 'ABERTA', tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tpp_p foreign key(parcelamento_id) references sigov.tributario_parcelamento(id), constraint ux_tpp unique(tenant_id,entidade_id,parcelamento_id,numero), constraint ck_tpp_val check(numero>0 and valor>0 and (valor_pago is null or valor_pago>=0)));
create table if not exists sigov.tributario_fiscalizacao (id bigint generated by default as identity primary key, numero_ordem varchar(60) not null, contribuinte_id bigint not null, tipo varchar(20) not null, fiscal_usuario_id bigint not null, inicio_at timestamptz, prazo date not null, termo_inicio text not null, defesa text, recurso text, resultado text, encerrada_at timestamptz, status varchar(20) not null default 'ABERTA', tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tf_c foreign key(contribuinte_id) references sigov.tributario_contribuinte(id), constraint fk_tf_u foreign key(fiscal_usuario_id) references sigov.usuario(id), constraint ux_tf_num unique(tenant_id,entidade_id,numero_ordem), constraint ck_tf_tipo check(tipo in('ISS','ALVARA','TAXA','IMOVEL','DENUNCIA','ROTINA')));
create table if not exists sigov.tributario_notificacao (id bigint generated by default as identity primary key, fiscalizacao_id bigint not null, numero varchar(60) not null, tipo varchar(40) not null, conteudo text not null, emitida_at timestamptz not null default now(), ciencia_at timestamptz, status varchar(20) not null default 'EMITIDA', tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tn_f foreign key(fiscalizacao_id) references sigov.tributario_fiscalizacao(id), constraint ux_tn_num unique(tenant_id,entidade_id,numero));
create table if not exists sigov.tributario_auto_infracao (id bigint generated by default as identity primary key, fiscalizacao_id bigint not null, numero varchar(60) not null, fundamento text not null, descricao text not null, valor_multa numeric(18,2) not null, defesa text, recurso text, status varchar(20) not null default 'LAVRADO', tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tai_f foreign key(fiscalizacao_id) references sigov.tributario_fiscalizacao(id), constraint ux_tai_num unique(tenant_id,entidade_id,numero), constraint ck_tai_val check(valor_multa>0));
create table if not exists sigov.tributario_certidao (id bigint generated by default as identity primary key, contribuinte_id bigint not null, tipo varchar(20) not null, codigo_validacao varchar(128) not null, emitida_at timestamptz not null default now(), validade date not null, fundamento text not null, situacao_fiscal jsonb not null, revogada_at timestamptz, revogacao_justificativa text, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint, constraint fk_tcert_c foreign key(contribuinte_id) references sigov.tributario_contribuinte(id), constraint ux_tcert_cod unique(codigo_validacao), constraint ck_tcert_tipo check(tipo in('NEGATIVA','POSITIVA','POSITIVA_EFEITO_NEGATIVA')));
create table if not exists sigov.tributario_auditoria (id bigint generated by default as identity primary key, usuario_id bigint, acao varchar(80) not null, recurso varchar(80) not null, recurso_id bigint, finalidade varchar(250) not null, correlation_id varchar(100), ip_hash varchar(128), dados_minimizados jsonb not null default '{}'::jsonb, ocorrido_at timestamptz not null default now(), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), created_by bigint, updated_at timestamptz, updated_by bigint, deleted_at timestamptz, deleted_by bigint);

create or replace function sigov.fn_tributario_validar_guia_paga() returns trigger language plpgsql as $$ begin if new.status='PAGA' and not exists(select 1 from sigov.tributario_pagamento p where p.guia_id=new.id and p.status='CONFIRMADO' and not p.is_deleted) then raise exception 'Guia paga exige pagamento confirmado'; end if; return new; end $$;
drop trigger if exists trg_tributario_guia_paga on sigov.tributario_guia; create constraint trigger trg_tributario_guia_paga after insert or update of status on sigov.tributario_guia deferrable initially deferred for each row execute function sigov.fn_tributario_validar_guia_paga();
create or replace function sigov.fn_tributario_validar_divida() returns trigger language plpgsql as $$ begin if not exists(select 1 from sigov.tributario_lancamento l where l.id=new.lancamento_id and l.tenant_id=new.tenant_id and l.entidade_id=new.entidade_id and l.vencimento<current_date and l.status in('VENCIDO','DIVIDA_ATIVA')) then raise exception 'Inscrição exige débito vencido'; end if; return new; end $$;
drop trigger if exists trg_tributario_divida on sigov.tributario_divida_ativa; create trigger trg_tributario_divida before insert or update of lancamento_id on sigov.tributario_divida_ativa for each row execute function sigov.fn_tributario_validar_divida();

create index if not exists ix_tributario_contribuinte_func09 on sigov.tributario_contribuinte(tenant_id,entidade_id,situacao,documento,inscricao_municipal) where not is_deleted;
create index if not exists ix_tributario_imovel_func09 on sigov.tributario_imovel(tenant_id,entidade_id,proprietario_id,situacao,inscricao_imobiliaria) where not is_deleted;
create index if not exists ix_tributario_mobiliario_func09 on sigov.tributario_mobiliario(tenant_id,entidade_id,contribuinte_id,situacao,inscricao_municipal) where not is_deleted;
create index if not exists ix_tributario_parametro_tributario_func09 on sigov.tributario_parametro_tributario(tenant_id,entidade_id,exercicio_id,tributo_id,vigencia_inicio) where not is_deleted;
create index if not exists ix_tributario_lancamento_func09 on sigov.tributario_lancamento(tenant_id,entidade_id,contribuinte_id,exercicio_id,tributo_id,status,vencimento) where not is_deleted;
create index if not exists ix_tributario_guia_func09 on sigov.tributario_guia(tenant_id,entidade_id,lancamento_id,status,vencimento) where not is_deleted;
create index if not exists ix_tributario_pagamento_func09 on sigov.tributario_pagamento(tenant_id,entidade_id,guia_id,pago_at,status) where not is_deleted;
create index if not exists ix_tributario_divida_ativa_func09 on sigov.tributario_divida_ativa(tenant_id,entidade_id,lancamento_id,status,numero_inscricao) where not is_deleted;
create index if not exists ix_tributario_parcelamento_func09 on sigov.tributario_parcelamento(tenant_id,entidade_id,contribuinte_id,status) where not is_deleted;
create index if not exists ix_tributario_fiscalizacao_func09 on sigov.tributario_fiscalizacao(tenant_id,entidade_id,contribuinte_id,status,prazo) where not is_deleted;
create index if not exists ix_tributario_certidao_func09 on sigov.tributario_certidao(tenant_id,entidade_id,contribuinte_id,tipo,emitida_at) where not is_deleted;
create index if not exists ix_tributario_auditoria_func09 on sigov.tributario_auditoria(tenant_id,entidade_id,recurso,recurso_id,ocorrido_at) where not is_deleted;
insert into sigov.permissao(modulo,chave,recurso,acao,descricao,ativo,is_deleted) select 'tributario',v.chave,v.recurso,v.acao,'Permissão FUNC09 Tributário',true,false from(values ('TRIBUTARIO_DASHBOARD_VIEW','tributario.dashboard','visualizar'),('TRIBUTARIO_CONTRIBUINTE_VIEW','tributario.contribuinte','visualizar'),('TRIBUTARIO_CONTRIBUINTE_MANAGE','tributario.contribuinte','gerenciar'),('TRIBUTARIO_IMOVEL_VIEW','tributario.imovel','visualizar'),('TRIBUTARIO_IMOVEL_MANAGE','tributario.imovel','gerenciar'),('TRIBUTARIO_MOBILIARIO_VIEW','tributario.mobiliario','visualizar'),('TRIBUTARIO_MOBILIARIO_MANAGE','tributario.mobiliario','gerenciar'),('TRIBUTARIO_PARAMETRO_VIEW','tributario.parametro','visualizar'),('TRIBUTARIO_PARAMETRO_MANAGE','tributario.parametro','gerenciar'),('TRIBUTARIO_LANCAMENTO_VIEW','tributario.lancamento','visualizar'),('TRIBUTARIO_LANCAMENTO_MANAGE','tributario.lancamento','gerenciar'),('TRIBUTARIO_GUIA_VIEW','tributario.guia','visualizar'),('TRIBUTARIO_GUIA_MANAGE','tributario.guia','gerenciar'),('TRIBUTARIO_ARRECADACAO_VIEW','tributario.arrecadacao','visualizar'),('TRIBUTARIO_ARRECADACAO_MANAGE','tributario.arrecadacao','gerenciar'),('TRIBUTARIO_DIVIDA_ATIVA_VIEW','tributario.divida_ativa','visualizar'),('TRIBUTARIO_DIVIDA_ATIVA_MANAGE','tributario.divida_ativa','gerenciar'),('TRIBUTARIO_PARCELAMENTO_VIEW','tributario.parcelamento','visualizar'),('TRIBUTARIO_PARCELAMENTO_MANAGE','tributario.parcelamento','gerenciar'),('TRIBUTARIO_FISCALIZACAO_VIEW','tributario.fiscalizacao','visualizar'),('TRIBUTARIO_FISCALIZACAO_MANAGE','tributario.fiscalizacao','gerenciar'),('TRIBUTARIO_CERTIDAO_VIEW','tributario.certidao','visualizar'),('TRIBUTARIO_CERTIDAO_MANAGE','tributario.certidao','gerenciar'),('TRIBUTARIO_RELATORIO_EXPORT','tributario.relatorio_export','gerenciar'),('TRIBUTARIO_AUDITORIA_VIEW','tributario.auditoria','visualizar'))v(chave,recurso,acao) where not exists(select 1 from sigov.permissao p where p.chave=v.chave);
insert into sigov.perfil_permissao(perfil_acesso_id,permissao_id,efeito,ativo,is_deleted) select pa.id,p.id,'PERMITIR',true,false from sigov.perfil_acesso pa cross join sigov.permissao p where pa.codigo_externo='SUPERADMIN' and pa.sistemico and pa.ativo and not pa.is_deleted and p.chave like 'TRIBUTARIO_%' and p.ativo and not p.is_deleted on conflict(perfil_acesso_id,permissao_id) do update set efeito='PERMITIR',ativo=true,is_deleted=false;
